<?php

namespace App\Models\HR;

use App\Models\Attendance\StaffAttendance;
use App\Models\Concerns\Auditable;
use App\Models\Concerns\BelongsToBranch;
use App\Models\Department;
use App\Models\User;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Database\Eloquent\SoftDeletes;

/**
 * Teacher or other employee of a branch. employee_code is generated by EmployeeService.
 * Salary and NID are confidential (employees.view-salary) and excluded from arrays/JSON and the audit trail.
 * Employees are never hard-deleted: status tracks resignation / termination / retirement.
 */
class Employee extends Model
{
    use Auditable, BelongsToBranch, SoftDeletes;

    public const TYPES = ['teacher', 'staff'];

    public const EMPLOYMENT_TYPES = ['permanent', 'contract', 'part_time', 'guest', 'probation'];

    public const STATUSES = ['active', 'suspended', 'resigned', 'terminated', 'retired'];

    /** Statuses that end employment (login account is deactivated). */
    public const SEPARATED = ['resigned', 'terminated', 'retired'];

    public const GENDERS = ['male', 'female', 'other'];

    protected $fillable = [
        'department_id', 'designation_id', 'employee_type', 'employment_type', 'name', 'name_bn', 'gender',
        'date_of_birth', 'phone', 'email', 'nid_number', 'blood_group', 'religion', 'present_address', 'permanent_address',
        'joining_date', 'qualification', 'experience_years', 'basic_salary', 'emergency_contact_name', 'emergency_contact_phone',
    ];

    protected $guarded = ['employee_code', 'user_id', 'status', 'photo_path'];

    protected $hidden = ['nid_number', 'basic_salary'];

    protected array $auditExclude = ['nid_number', 'basic_salary'];

    protected function casts(): array
    {
        return [
            'date_of_birth' => 'date',
            'joining_date' => 'date',
            'status_changed_on' => 'date',
            'experience_years' => 'float',
            'basic_salary' => 'decimal:2',
            'user_id' => 'integer',
            'department_id' => 'integer',
            'designation_id' => 'integer',
            'branch_id' => 'integer',
            'institution_id' => 'integer',
        ];
    }

    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class);
    }

    /** Salary structure (Part 4 payroll). */
    public function salary(): \Illuminate\Database\Eloquent\Relations\HasOne
    {
        return $this->hasOne(\App\Models\Finance\EmployeeSalary::class);
    }

    public function department(): BelongsTo
    {
        return $this->belongsTo(Department::class);
    }

    public function designation(): BelongsTo
    {
        return $this->belongsTo(Designation::class);
    }

    public function documents(): HasMany
    {
        return $this->hasMany(EmployeeDocument::class)->latest();
    }

    public function histories(): HasMany
    {
        return $this->hasMany(EmploymentHistory::class)->orderByDesc('effective_on')->orderByDesc('id');
    }

    public function leaveApplications(): HasMany
    {
        return $this->hasMany(LeaveApplication::class)->latest('from_date');
    }

    public function attendances(): HasMany
    {
        return $this->hasMany(StaffAttendance::class);
    }

    public function scopeActive(Builder $query): Builder
    {
        return $query->where('status', 'active');
    }

    public function scopeTeachers(Builder $query): Builder
    {
        return $query->where('employee_type', 'teacher');
    }

    public function scopeSearch(Builder $query, ?string $term): Builder
    {
        if (! $term) {
            return $query;
        }

        return $query->where(function (Builder $q) use ($term) {
            $q->where('employees.name', 'like', "%{$term}%")
                ->orWhere('employees.name_bn', 'like', "%{$term}%")
                ->orWhere('employees.employee_code', 'like', "%{$term}%")
                ->orWhere('employees.phone', 'like', "%{$term}%")
                ->orWhere('employees.email', 'like', "%{$term}%");
        });
    }

    public function isActive(): bool
    {
        return $this->status === 'active';
    }

    public function isSeparated(): bool
    {
        return in_array($this->status, self::SEPARATED, true);
    }

    public function displayName(): string
    {
        return app()->getLocale() === 'bn' && $this->name_bn ? $this->name_bn : $this->name;
    }

    public function initials(): string
    {
        $parts = preg_split('/\s+/', trim($this->name)) ?: [];

        return mb_strtoupper(mb_substr($parts[0] ?? '', 0, 1).mb_substr($parts[1] ?? '', 0, 1));
    }
}
